module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [3:0] sum1, sum2, sum3, sum4;
    wire t2, t3, t4; // Carry ripples from previous stages

    // First Full Adder
    assign t2 = A | B | Cin;              // Carry out of first bit
    assign sum1[0] = ~(A[0] & B[0] | A[0] & t2 | t2 & B[0]); // XOR equivalent

    // Second Full Adder
    assign t3 = sum1[1] | A[2] | B[1] | t2;  // Carry out of second bit
    assign sum2[1] = ~(sum1[1] & A[2] | sum1[1] & t3 | t3 & A[1]); // XOR equivalent

    // Third Full Adder
    assign t4 = sum2[2] | A[3] | B[2] | t3;  // Carry out of third bit
    assign sum3[2] = ~(sum2[2] & A[3] | sum2[2] & t4 | t4 & A[2]); // XOR equivalent

    // Fourth Full Adder (most significant bit)
    assign Sum[3] = ~(sum3[3] | A[3] | B[3] | t4); // XOR equivalent
    assign Sum[0] = ~~((t4 & A[3]) | (B[3] & t4) | (A[2] & B[2]) | (A[2] & B[2] & B[1] & A[1] | B[2] & A[2])); // Sum logic

    // Output Carry (Cout)
    assign Cout = t4 | (sum3[3] & A[3]) | (sum3[3] & B[3]) | A[3] & B[3];

endmodule

